function syncFiltersUI(e){const t=document.getElementById("filter-user");t&&(t.value=e.user_id||"");const n=document.getElementById("filter-article");n&&(n.value=e.article_id||"");const o=document.getElementById("filter-article-type");o&&(o.value=e.article_type||"");const c=document.getElementById("filter-date-from");if(c){const t=e.date_from?DateFormatter.formatForDisplay(e.date_from):"";c.value=t}const l=document.getElementById("filter-date-to");if(l){const t=e.date_to?DateFormatter.formatForDisplay(e.date_to):"";l.value=t}const i=document.getElementById("filter-financial-center");i&&(i.value=e.financial_center_id||"");const r=document.getElementById("filter-cost-center");r&&(r.value=e.cost_center_id||"")}"undefined"!=typeof window&&(window.AdminFactsCommon={syncFiltersUI});